package io.github.pnoker.common.manager.service.impl;
import io.github.pnoker.common.enums.EntityTypeEnum;import io.github.pnoker.common.exception.NotFoundException;import io.github.pnoker.common.manager.service.*;import lombok.RequiredArgsConstructor;import org.springframework.stereotype.Service;import reactor.core.publisher.Mono;
@Service @RequiredArgsConstructor public class ReactiveEntityTenantServiceImpl implements ReactiveEntityTenantService{private final ReactiveDriverService drivers;private final ReactiveProfileService profiles;private final ReactivePointService points;private final ReactiveDeviceService devices;public Mono<Void> requireEntityTenant(Long tenant,EntityTypeEnum type,Long id){if(type==null)return Mono.error(new NotFoundException("Resource does not exist"));return switch(type){case DRIVER->drivers.getById(tenant,id).then();case PROFILE->profiles.getById(tenant,id).then();case POINT->points.getById(tenant,id).then();case DEVICE->devices.getById(tenant,id).then();default->Mono.error(new NotFoundException("Resource does not exist"));};}}
